def tidy_open_followups(apps, schema_editor):
    """Before one-open-per-kind is enforced: keep the soonest open reminder of each kind per
    conversation and close the copies; manual reminders go on their author's list."""
    from django.utils import timezone

    FollowUp = apps.get_model("conversations", "FollowUp")
    seen = set()
    now = timezone.now()
    for f in FollowUp.objects.filter(
        done_at__isnull=True, conversation__isnull=False
    ).order_by("conversation_id", "source", "due_at", "id"):
        key = (f.conversation_id, f.source)
        if key in seen:
            f.done_at = now
            f.closed_reason = "cancelled"
            f.save(update_fields=["done_at", "closed_reason"])
        else:
            seen.add(key)
    FollowUp.objects.filter(
        source="manual", assigned_to__isnull=True, created_by__isnull=False
    ).update(assigned_to=models.F("created_by"))


